SUMMARY = {"avg": None, "count": None, "url": None}   # overall Amazon rating shown top right (optional)

BOOK_TITLE = {"beginner": "The Padel Playbook: Beginner & Intermediate", "advanced": "The Padel Playbook: Intermediate & Advanced",
              "drill": "The Padel Drill Book", "drill2": "The Padel Drill Book: Intermediate & Advanced", "kids": "The Padel Playbook: Kids Edition"}
CHECK = '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="8" fill="#2E7D4F"/><path d="M4.5 8.3l2.2 2.2 4.8-4.9" fill="none" stroke="#fff" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>'

def card(r, show_book=True):
    vp = f'<span class="vp">{CHECK}Amazon Verified Purchase</span>' if r.get("verified") else ""
    book = f'<span class="rv-book">{E(BOOK_TITLE[r["book"]])}</span>' if show_book and r.get("book") else ""
    stars = "★" * r["stars"]
    link = f' · <a href="{E(r["url"])}" rel="noopener" target="_blank">Read on Amazon →</a>' if r.get("url") else ""
    return (f'<article class="rv-card">{book}<div class="rv-body"><div class="rv-top"><span class="stars" aria-label="{r["stars"]} out of 5 stars">{stars}</span>{vp}</div>'
            f'<h3>{E(r["title"])}</h3><blockquote>{E(r["text"])}</blockquote></div>'
            f'<div class="rv-who"><strong>{E(r["name"])}</strong><span class="rv-meta">Reviewed in {E(r["country"])} on {E(r["date"])}{link}</span></div></article>')

def section(book=None, limit=3, css=False):
    rs = [r for r in REVIEWS if r["stars"] == 5 and (book is None or r["book"] == book)][:limit]
    if not rs:
        return ""
    score = ""
    if SUMMARY.get("avg") and book is None:
        score = f'<div class="rv-score"><b>{E(str(SUMMARY["avg"]))}</b><span><span class="stars" aria-hidden="true">★★★★★</span><br>Average on Amazon · {E(str(SUMMARY["count"]))} ratings</span></div>'
    foot = f' <a href="{E(SUMMARY["url"])}" rel="noopener" target="_blank">See all reviews on Amazon →</a>' if SUMMARY.get("url") else ""
    link = '<link rel="stylesheet" href="/reviews.css?v=1">' if css else ''
    return (f'{link}<section class="rv" id="reviews"><div class="wrap"><div class="rv-head"><div><div class="eyebrow">Reader reviews</div><h2>What players say</h2></div>{score}</div>'
            f'<div class="rv-grid">{"".join(card(r, book is None) for r in rs)}</div>'
            f'<p class="rv-foot">Reviews quoted from Amazon customer reviews of our books.{foot}</p></div></section>')
